import csv, io, os, re
from datetime import datetime


def _num(s):
    if s is None:
        return None
    t = re.sub(r'[\s\u00a0\u202f]', '', str(s)).replace('Kč', '')
    if not t:
        return None
    if ',' in t:
        t = t.replace('.', '').replace(',', '.')
    try:
        return float(t)
    except ValueError:
        return None


def _date(s):
    s = (s or '').strip()
    for f in ('%d.%m.%Y', '%d. %m. %Y', '%Y-%m-%d', '%d/%m/%Y'):
        try:
            return datetime.strptime(s, f).date().isoformat()
        except ValueError:
            pass
    return None


def _read(path):
    raw = open(path, 'rb').read()
    try:
        t = raw.decode('utf-8-sig')
    except UnicodeDecodeError:
        t = raw.decode('cp1250', errors='replace')
    first = t.split('\n', 1)[0]
    delim = ';' if first.count(';') >= first.count(',') else ','
    rows = list(csv.DictReader(io.StringIO(t), delimiter=delim))
    return [{(k or '').strip(): (v or '').strip() for k, v in r.items()} for r in rows]


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder']:
        raise ValueError('input must contain a non-empty string field folder')
    base = os.path.join('.', 'inbox', inp['folder'])
    if not os.path.isdir(base):
        raise ValueError('folder not found: ' + inp['folder'])
    out = {'bank_transactions': [], 'customer_invoices': [], 'errors': []}
    p = os.path.join(base, 'bank_statement.csv')
    if os.path.exists(p):
        for i, r in enumerate(_read(p), 2):
            a = _num(r.get('Částka'))
            d = _date(r.get('Datum'))
            if a is None or d is None:
                out['errors'].append('bank_statement.csv line %d unparsable' % i)
                continue
            out['bank_transactions'].append({
                'date': d, 'amount': a, 'currency': r.get('Měna') or 'CZK',
                'counterparty': r.get('Protistrana', ''), 'variable_symbol': r.get('VS', ''),
                'message': r.get('Zpráva', ''), 'balance': _num(r.get('Zůstatek'))})
    else:
        out['errors'].append('bank_statement.csv missing')
    p = os.path.join(base, 'customer_invoices.csv')
    if os.path.exists(p):
        for i, r in enumerate(_read(p), 2):
            a = _num(r.get('castka_kc'))
            if a is None or not r.get('cislo_faktury'):
                out['errors'].append('customer_invoices.csv line %d unparsable' % i)
                continue
            out['customer_invoices'].append({
                'invoice_number': r['cislo_faktury'], 'customer': r.get('odberatel', ''),
                'issue_date': _date(r.get('datum_vystaveni')),
                'due_date': _date(r.get('datum_splatnosti')), 'amount_czk': a})
    else:
        out['errors'].append('customer_invoices.csv missing')
    return out

